&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Ankou&lt;div style=&quot;float:right;&quot;&gt;FP 14&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;Bestiare 4 Page 13&lt;/li&gt;&lt;li&gt;38 400 &lt;b&gt;PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-F&#233;e.html&quot; title=&quot;F&#233;e&quot;&gt;F&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Extraplanaire.html&quot; title=&quot;Extraplanaire (sous-type)&quot;&gt;extraplanaire&lt;/a&gt;) de taille G, LM&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init&lt;/b&gt; +13&#160;; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; 36&#160;m, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;&#160;; &lt;b&gt;Perception&lt;/b&gt;&#160;+21 &lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#201;FENSE&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt;&#160;31, contact 19, pris au d&#233;pourvu 21 (Dex +9, esquive +1, naturelle +12, taille -1)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv&lt;/b&gt; 133 (14d6+84)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f&lt;/b&gt; +18, &lt;b&gt;Vig&lt;/b&gt; +10, &lt;b&gt;Vol&lt;/b&gt; +13&lt;/li&gt;&lt;li&gt;&lt;b&gt;RD&lt;/b&gt; 10/&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ferfroid.html&quot; title=&quot;fer froid&quot;&gt;fer froid&lt;/a&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;ATTAQUE&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD&lt;/b&gt; vol 27&#160;m (parfaite)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; 2 griffes, +14 (1d6+8) et coup de queue, +9 (1d8+4 plus saignement) et 2 ailes, +9 (1d8+4 plus saignement) Espace 3&#160;m&#160;; Allonge 1,50&#160;m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaque sournoise&lt;/a&gt; +3d6, doubles d’ombre, fer froid assassin, &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; (2d6)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (NLS 15&#160;; concentration +22)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#192; volont&#233;&lt;/b&gt;— &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-D&#233;puisement.html&quot; title=&quot;Rayon d&amp;#39;&#233;puisement&quot;&gt;rayon d’&#233;puisement&lt;/a&gt;&lt;/i&gt; (DD&#160;20), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Silence.html&quot; title=&quot;Silence&quot;&gt;silence&lt;/a&gt;&lt;/i&gt; (sur lui seulement), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres-Profondes.html&quot; title=&quot;T&#233;n&#232;bres profondes&quot;&gt;t&#233;n&#232;bres profondes&lt;/a&gt;&lt;/i&gt;,&lt;/li&gt;&lt;li&gt;&lt;b&gt;3/jour&lt;/b&gt;— &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ancre-Dimensionnelle.html&quot; title=&quot;Ancre dimensionnelle&quot;&gt;ancre dimensionnelle&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation-Supr&#234;me.html&quot; title=&quot;T&#233;l&#233;portation supr&#234;me&quot;&gt;t&#233;l&#233;portation supr&#234;me&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;1/jour&lt;/b&gt;— &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-De-Mort.html&quot; title=&quot;Cercle de mort&quot;&gt;cercle de mort&lt;/a&gt;&lt;/i&gt; (DD&#160;23), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Localisation-Supr&#234;me.html&quot; title=&quot;Localisation supr&#234;me&quot;&gt;localisation supr&#234;me&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayons-Prismatiques.html&quot; title=&quot;Rayons prismatiques&quot;&gt;rayons prismatiques&lt;/a&gt;&lt;/i&gt; (DD&#160;24) &lt;br /&gt;&lt;div class=&quot;box&quot;&gt;STATISTIQUES&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For&lt;/b&gt; 26, &lt;b&gt;Dex&lt;/b&gt; 28, &lt;b&gt;Con&lt;/b&gt; 22, &lt;b&gt;Int&lt;/b&gt; 17, &lt;b&gt;Sag&lt;/b&gt; 19, &lt;b&gt;Cha&lt;/b&gt; 25&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA&lt;/b&gt; +7 ; &lt;b&gt;BMO&lt;/b&gt; +16 ; &lt;b&gt;DMD&lt;/b&gt; 36&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Vol.html&quot; title=&quot;Attaque en vol&quot;&gt;Attaque en vol&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-En-Aveugle.html&quot; title=&quot;Combat en aveugle&quot;&gt;Combat en aveugle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Comme-L&#233;clair.html&quot; title=&quot;Comme l&amp;#39;&#233;clair&quot;&gt;Comme l’&#233;clair&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Comme-Le-Vent.html&quot; title=&quot;Comme le vent&quot;&gt;Comme le vent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +22, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) +20, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) +17, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; +26, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +21, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +21, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +21, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +32&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues&lt;/b&gt; commun, sylvestre (incapable de parler)&#160;; &lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;pathie-(Capacit&#233;).html&quot; title=&quot;T&#233;l&#233;pathie (Sur)&quot;&gt;t&#233;l&#233;pathie&lt;/a&gt; 30&#160;m &lt;br /&gt;&lt;div class=&quot;box&quot;&gt;&#201;COLOGIE&lt;/div&gt;)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Environnement&lt;/b&gt; tous (pays primaire des f&#233;es)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Organisation&lt;/b&gt; solitaire&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard &lt;br /&gt;&lt;div class=&quot;box&quot;&gt;POUVOIRS SP&#201;CIAUX&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Doubles d’ombre (Sur).&lt;/b&gt; Une fois par jour par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, l’ankou peut invoquer jusqu’&#224; quatre doubles d’ombre de sa personne. Ils apparaissent al&#233;atoirement dans un rayon de 18&#160;m&#232;tres autour de lui et restent pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal &#224; son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; (en g&#233;n&#233;ral donc 7&#160;rounds). Ces doubles sont identiques &#224; l’original mais ils n’ont que 20% des points de vie totaux de leur mod&#232;le (c’est-&#224;-dire 26&#160;&lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt; s’ils sont convoqu&#233;s par un ankou disposant de tous ses pv). Les doubles b&#233;n&#233;ficient de toutes les attaques de corps &#224; corps et de tous les pouvoirs de l’ankou original mais ils sont incapables de cr&#233;er des doubles et d’utiliser ses pouvoirs magiques, en dehors de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres-Profondes.html&quot; title=&quot;T&#233;n&#232;bres profondes&quot;&gt;t&#233;n&#232;bres profondes&lt;/a&gt;&lt;/i&gt;. Une cr&#233;ature qui interagit avec un double a droit &#224; un jet de Volont&#233; pour r&#233;futer l’illusion (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;&#160;10 + 1/2 DV de l’ankou + modificateur de Charisme de l’ankou, soit g&#233;n&#233;ralement DD&#160;24). Si une cr&#233;ature r&#233;ussit le jet et comprend qu’elle a affaire &#224; un double, celui-ci fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dombres.html&quot; title=&quot;Convocation d&amp;#39;ombres&quot;&gt;convocation d’ombres&lt;/a&gt;&lt;/i&gt;. Les doubles d’ombre subissent le double de d&#233;g&#226;ts inflig&#233;s par les sorts du registre de la lumi&#232;re. Si le v&#233;ritable ankou se fait tuer, s’il tombe &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; ou s’il s’&#233;loigne &#224; plus de 36&#160;m&#232;tres d’un double, les doubles disparaissent automatiquement.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Fer froid assassin (Sur).&lt;/b&gt; En ce qui concerne la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;duction de d&#233;g&#226;ts&lt;/a&gt;, toutes les armes naturelles de l’ankou sont consid&#233;r&#233;es comme &#233;tant en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ferfroid.html&quot; title=&quot;fer froid&quot;&gt;fer froid&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;i&gt;Cette ignoble cr&#233;ature squelettique envelopp&#233;e d’ailes de t&#233;n&#232;bres semble br&#251;ler de l’int&#233;rieur.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les ankous sont des assassins au service de puissants nobles f&#233;eriques qui les envoient pour tuer, terrifier et torturer en leur nom. Ils ne parlent jamais et se contentent de murmurer par t&#233;l&#233;pathie le verdict de leur seigneur &#224; leur victime. Un ankou mesure g&#233;n&#233;ralement trois m&#232;tres de haut pour une envergure de deux m&#232;tres cinquante mais il p&#232;se moins de cinquante kilos.
&lt;/div&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;center&gt;&lt;img src=&quot;/wiki/public/upload/Bestiaire/Ankou_img.jpg&quot; width=&quot;95%&quot; style=&quot;float: none; margin: 5px;&quot;/&gt;&lt;/center&gt;
